create policy erp_branch_owner_write on public.erp_branches for all to authenticated using(public.current_finance_role()='OWNER' and exists(select 1 from public.erp_schools s where s.id=school_id and public.can_access_organization(s.organization_id))) with check(public.current_finance_role()='OWNER' and exists(select 1 from public.erp_schools s where s.id=school_id and public.can_access_organization(s.organization_id)));
create policy erp_division_owner_write on public.erp_divisions for all to authenticated using(public.current_finance_role()='OWNER' and exists(select 1 from public.erp_schools s where s.id=school_id and public.can_access_organization(s.organization_id))) with check(public.current_finance_role()='OWNER' and exists(select 1 from public.erp_schools s where s.id=school_id and public.can_access_organization(s.organization_id)));
